CREATE TABLE admin_user (id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) UNIQUE NOT NULL, password_hash VARCHAR(100) NOT NULL, nickname VARCHAR(50) NOT NULL, email VARCHAR(100), avatar_url VARCHAR(1000), enabled TINYINT DEFAULT 1, last_login_at TIMESTAMP, created_at TIMESTAMP, updated_at TIMESTAMP);
CREATE TABLE blog_column (id BIGINT AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(120) UNIQUE NOT NULL, name_zh VARCHAR(100), name_en VARCHAR(100), description_zh VARCHAR(1000), description_en VARCHAR(1000), status VARCHAR(20), sort_order INT, created_at TIMESTAMP, updated_at TIMESTAMP);
CREATE TABLE blog_article (id BIGINT AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(160) UNIQUE NOT NULL, title VARCHAR(255), summary VARCHAR(1000), content CLOB, column_id BIGINT, status VARCHAR(20), published_at TIMESTAMP, view_count BIGINT DEFAULT 0, read_minutes INT, created_at TIMESTAMP, updated_at TIMESTAMP);
CREATE TABLE blog_tag (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(50) UNIQUE NOT NULL, color VARCHAR(20), created_at TIMESTAMP, updated_at TIMESTAMP);
CREATE TABLE blog_article_tag (article_id BIGINT NOT NULL, tag_id BIGINT NOT NULL, PRIMARY KEY(article_id, tag_id));
CREATE TABLE site_profile (id BIGINT PRIMARY KEY, display_name_zh VARCHAR(100), display_name_en VARCHAR(100), role_zh VARCHAR(255), role_en VARCHAR(255), hero_description_zh VARCHAR(1000), hero_description_en VARCHAR(1000), about_paragraph1_zh CLOB, about_paragraph1_en CLOB, about_paragraph2_zh CLOB, about_paragraph2_en CLOB, contact_heading_zh VARCHAR(500), contact_heading_en VARCHAR(500), contact_description_zh VARCHAR(1000), contact_description_en VARCHAR(1000), email VARCHAR(100), avatar_url VARCHAR(1000), footer_zh VARCHAR(500), footer_en VARCHAR(500), stat1_value VARCHAR(30), stat1_label_zh VARCHAR(100), stat1_label_en VARCHAR(100), stat2_value VARCHAR(30), stat2_label_zh VARCHAR(100), stat2_label_en VARCHAR(100), stat3_value VARCHAR(30), stat3_label_zh VARCHAR(100), stat3_label_en VARCHAR(100), stat4_value VARCHAR(30), stat4_label_zh VARCHAR(100), stat4_label_en VARCHAR(100), updated_at TIMESTAMP);
CREATE TABLE portfolio_project (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150), subtitle_zh VARCHAR(255), subtitle_en VARCHAR(255), description_zh VARCHAR(1000), description_en VARCHAR(1000), tech_stack VARCHAR(1000), project_url VARCHAR(1000), image_url VARCHAR(1000), sort_order INT, enabled TINYINT, created_at TIMESTAMP, updated_at TIMESTAMP);
CREATE TABLE career_experience (id BIGINT AUTO_INCREMENT PRIMARY KEY, period_zh VARCHAR(100), period_en VARCHAR(100), role_zh VARCHAR(255), role_en VARCHAR(255), organization_zh VARCHAR(255), organization_en VARCHAR(255), description_zh VARCHAR(1000), description_en VARCHAR(1000), sort_order INT, enabled TINYINT, created_at TIMESTAMP, updated_at TIMESTAMP);
CREATE TABLE site_skill (id BIGINT AUTO_INCREMENT PRIMARY KEY, group_zh VARCHAR(100), group_en VARCHAR(100), name VARCHAR(150), proficiency INT, sort_order INT, enabled TINYINT, created_at TIMESTAMP, updated_at TIMESTAMP);
CREATE TABLE social_link (id BIGINT AUTO_INCREMENT PRIMARY KEY, platform VARCHAR(100), handle VARCHAR(150), url VARCHAR(1000), icon VARCHAR(100), sort_order INT, enabled TINYINT, created_at TIMESTAMP, updated_at TIMESTAMP);
CREATE TABLE media_asset (id BIGINT AUTO_INCREMENT PRIMARY KEY, qiniu_key VARCHAR(500) UNIQUE, url VARCHAR(1000), original_name VARCHAR(255), mime_type VARCHAR(100), size_bytes BIGINT, content_hash VARCHAR(64) UNIQUE, created_at TIMESTAMP);
CREATE TABLE operation_log (id BIGINT AUTO_INCREMENT PRIMARY KEY, admin_id BIGINT, module VARCHAR(50), action VARCHAR(255), http_method VARCHAR(10), success TINYINT, created_at TIMESTAMP);
CREATE TABLE daily_visit_stat (stat_date DATE PRIMARY KEY, pv BIGINT, uv BIGINT);
